  str = opts.trim ? str.trim() : str;
  str = opts.lowerCase ? str.toLowerCase() : str;
  if (opts.transliteration) {
    str = transliterate(str, opts.transliterationTo);
  }
  str = escapeStringRegexp(str);
  if (opts.maxLength !== Infinity) {
    str = str.substring(0, opts.maxLength);
  }
  return str;
}

module.exports = slugify;
