import { transliterate } from '@sindresorhus/transliterate';
import escapeStringRegexp from 'escape-string-regexp';

const defaultOptions = {
  replacement: '-',
  strict: false,
  locale: 'en',
  maxLength: Infinity,
};

type Options = {
  replacement: string;
  strict: boolean;
  locale: string;
  maxLength: number;
};

function slugify(str: string, options: Options = defaultOptions): string {
  let slug = str;

  if (options.strict) {
    slug = slug.replace(/[^a-z0-9]/gi, '');
  } else {
    slug = slug.toLowerCase();
  }

  slug = slug.replace(/[^a-z0-9]/g, options.replacement);

  if (options.maxLength !== Infinity) {
    slug = slug.slice(0, options.maxLength);
  }

  return slug;
}
